B.aip=new A.ro([B.dN,"\u0646\u0648\u0636\u0651\u062d \u0627\u0644\u062e\u0644\u0627\u0641 \u0648\u0644\u0627 \u0646\u0631\u062c\u0651\u062d","\u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f\u064a\u0629 \u0646\u0628\u064a\u0651\u0646 \u0627\u0644\u0645\u062a\u0641\u0642 \u0639\u0644\u064a\u0647 \u0648\u0646\u062a\u0631\u0643 \u0627\u0644\u062a\u0631\u062c\u064a\u062d \u0644\u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645.","We explain differences, we do not choose","On matters of ijtihad we show what is agreed and leave the choice between views to scholars."])
B.ain=new A.ro([B.bt,"\u062d\u0627\u0644\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0644\u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645","\u0644\u0627 \u0646\u064f\u0635\u062f\u0631 \u0641\u062a\u0648\u0649 \u0641\u064a \u0648\u0642\u0627\u0626\u0639 \u0628\u0639\u064a\u0646\u0647\u0627\u060c \u0628\u0644 \u0646\u062d\u064a\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0645\u062e\u062a\u0635.","Your personal case goes to scholars","We do not issue fatwas on specific situations; we refer you to a specialist."])
B.aio=new A.ro([B.j6,"\u0623\u0633\u0626\u0644\u0629 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0642\u0637","\u062a\u062c\u064a\u0628 \u0628\u0635\u064a\u0631\u0629 \u0639\u0645\u0651\u0627 \u064a\u0642\u0648\u0644\u0647 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0642\u0637\u060c \u0644\u0627 \u0639\u0646 \u0627\u0644\u0648\u0635\u0641\u0627\u062a \u0623\u0648 \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0623\u0648 \u062a\u0639\u0627\u0644\u064a\u0645 \u0627\u0644\u0623\u062f\u064a\u0627\u0646 \u0627\u0644\u0623\u062e\u0631\u0649.","Questions about Islam only","Basirah only answers what Islam says, not recipes, news or the teachings of other religions."])
